+/************************************************************************/
+/*                      NITFComplexRasterBand()                         */
+/************************************************************************/
+
+NITFComplexRasterBand::NITFComplexRasterBand(NITFDataset *poDSIn,
+                                             GDALRasterBand *poBandI,
+                                             GDALRasterBand *poBandQ,
+                                             int nIBand, int nQBand)
+    : NITFRasterBand(poDSIn, nIBand)
+{
+
+    CPLAssert(poBandI->GetRasterDataType() == poBandQ->GetRasterDataType());
+    underlyingDataType = poBandI->GetRasterDataType();
+
+    //add the I and Q bands to an intermediate dataset
+    poIntermediateDS = std::make_unique<NITFDataset>();
+    poIntermediateDS->nRasterXSize = poDSIn->nRasterXSize;
+    poIntermediateDS->nRasterYSize = poDSIn->nRasterYSize;
+    poIntermediateDS->eAccess = poDSIn->eAccess;
+
+    poIntermediateDS->SetBand(nIBand, poBandI);
+    poIntermediateDS->SetBand(nQBand, poBandQ);
+
+    anBandMap[0] = nIBand;
+    anBandMap[1] = nQBand;
+
+    //set the new datatype
+    switch (underlyingDataType)
+    {
+        case GDT_Int16:
+            eDataType = GDT_CInt16;
+            break;
+        case GDT_Int32:
+            eDataType = GDT_CInt32;
+            break;
+        case GDT_Float32:
+            eDataType = GDT_CFloat32;
+            break;
+        case GDT_Float64:
+            eDataType = GDT_CFloat64;
+            break;
+        default:
+            eDataType = GDT_Unknown;
+            CPLError(CE_Failure, CPLE_NotSupported,
+                     "Unsupported complex datatype");
+            break;
+    }
+
+    complexDataTypeSize = GDALGetDataTypeSizeBytes(eDataType);
+    underlyingDataTypeSize = GDALGetDataTypeSizeBytes(underlyingDataType);
+    CPLAssert(underlyingDataTypeSize * 2 == complexDataTypeSize);
+
+    poBandI->GetBlockSize(&nBlockXSize, &nBlockYSize);
+}
+
+/************************************************************************/
+/*                             IReadBlock()                             */
+/************************************************************************/
+
+CPLErr NITFComplexRasterBand::IBlockIO(int nBlockXOff, int nBlockYOff,
+                                       void *pImage, GDALRWFlag rwFlag)
+
+{
+    int nRequestYSize;
+    int nRequestXSize;
+    bool bMemset = false;
+
+    /* -------------------------------------------------------------------- */
+    /*      If the last strip is partial, we need to avoid                  */
+    /*      over-requesting.  We also need to initialize the extra part     */
+    /*      of the block to zero.                                           */
+    /* -------------------------------------------------------------------- */
+    if ((nBlockYOff + 1) * nBlockYSize > nRasterYSize)
+    {
+        nRequestYSize = nRasterYSize - nBlockYOff * nBlockYSize;
+        if (rwFlag == GF_Read)
+            bMemset = true;
+    }
+    else
+    {
+        nRequestYSize = nBlockYSize;
+    }
+
+    /*-------------------------------------------------------------------- */
+    /*      If the input imagery is tiled, also need to avoid over-        */
+    /*      requesting in the X-direction.                                 */
+    /* ------------------------------------------------------------------- */
+    if ((nBlockXOff + 1) * nBlockXSize > nRasterXSize)
+    {
+        nRequestXSize = nRasterXSize - nBlockXOff * nBlockXSize;
+        if (rwFlag == GF_Read)
+            bMemset = true;
+    }
+    else
+    {
+        nRequestXSize = nBlockXSize;
+    }
+
+    if (bMemset)
+    {
+        memset(pImage, 0,
+               static_cast<size_t>(GDALGetDataTypeSizeBytes(eDataType)) *
+                   nBlockXSize * nBlockYSize);
+    }
+
+    //read/write both bands with interleaved pixels
+    return poIntermediateDS->RasterIO(
+        rwFlag, nBlockXOff * nBlockXSize, nBlockYOff * nBlockYSize,
+        nRequestXSize, nRequestYSize, pImage, nRequestXSize, nRequestYSize,
+        underlyingDataType, 2, &anBandMap[0], complexDataTypeSize,
+        complexDataTypeSize * nBlockXSize, underlyingDataTypeSize, nullptr);","path":"frmts/nitf/nitfrasterband.cpp","commit_id":"3d631bc58addfc4ef0bf7281906870ee0392e413","original_commit_id":"3d631bc58addfc4ef0bf7281906870ee0392e413","user":{"login":"github-advanced-security[bot]","id":62310815,"node_id":"MDM6Qm90NjIzMTA4MTU=","avatar_url":"https://avatars.githubusercontent.com/in/57789?v=4","gravatar_id":"","url":"https://api.github.com/users/github-advanced-security%5Bbot%5D","html_url":"https://github.com/apps/github-advanced-security","followers_url":"https://api.github.com/users/github-advanced-security%5Bbot%5D/followers","following_url":"https://api.github.com/users/github-advanced-security%5Bbot%5D/following{/other_user}","gists_url":"https://api.github.com/users/github-advanced-security%5Bbot%5D/gists{/gist_id}","starred_url":"https://api.github.com/users/github-advanced-security%5Bbot%5D/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/github-advanced-security%5Bbot%5D/subscriptions","organizations_url":"https://api.github.com/users/github-advanced-security%5Bbot%5D/orgs","repos_url":"https://api.github.com/users/github-advanced-security%5Bbot%5D/repos","events_url":"https://api.github.com/users/github-advanced-security%5Bbot%5D/events{/privacy}","received_events_url":"https://api.github.com/users/github-advanced-security%5Bbot%5D/received_events","type":"Bot","user_view_type":"public","site_admin":false},"body":"## Multiplication result converted to larger type

